package com.mbolt.casino.block.decor;

/**
 * The characters a neon letter can show, in the order of art/neon_font.txt. Generated by art/neon.py from that
 * font; edit the font and run the script instead of editing this file.
 */
public enum NeonGlyph {
    A("a", 'A'),
    B("b", 'B'),
    C("c", 'C'),
    D("d", 'D'),
    E("e", 'E'),
    F("f", 'F'),
    G("g", 'G'),
    H("h", 'H'),
    I("i", 'I'),
    J("j", 'J'),
    K("k", 'K'),
    L("l", 'L'),
    M("m", 'M'),
    N("n", 'N'),
    O("o", 'O'),
    P("p", 'P'),
    Q("q", 'Q'),
    R("r", 'R'),
    S("s", 'S'),
    T("t", 'T'),
    U("u", 'U'),
    V("v", 'V'),
    W("w", 'W'),
    X("x", 'X'),
    Y("y", 'Y'),
    Z("z", 'Z'),
    DIGIT_0("digit_0", '0'),
    DIGIT_1("digit_1", '1'),
    DIGIT_2("digit_2", '2'),
    DIGIT_3("digit_3", '3'),
    DIGIT_4("digit_4", '4'),
    DIGIT_5("digit_5", '5'),
    DIGIT_6("digit_6", '6'),
    DIGIT_7("digit_7", '7'),
    DIGIT_8("digit_8", '8'),
    DIGIT_9("digit_9", '9'),
    CYRILLIC_BE("cyrillic_be", 'Б'),
    CYRILLIC_GHE("cyrillic_ghe", 'Г'),
    CYRILLIC_DE("cyrillic_de", 'Д'),
    CYRILLIC_YO("cyrillic_yo", 'Ё'),
    CYRILLIC_ZHE("cyrillic_zhe", 'Ж'),
    CYRILLIC_ZE("cyrillic_ze", 'З'),
    CYRILLIC_I("cyrillic_i", 'И'),
    CYRILLIC_SHORT_I("cyrillic_short_i", 'Й'),
    CYRILLIC_EL("cyrillic_el", 'Л'),
    CYRILLIC_PE("cyrillic_pe", 'П'),
    CYRILLIC_U("cyrillic_u", 'У'),
    CYRILLIC_EF("cyrillic_ef", 'Ф'),
    CYRILLIC_TSE("cyrillic_tse", 'Ц'),
    CYRILLIC_CHE("cyrillic_che", 'Ч'),
    CYRILLIC_SHA("cyrillic_sha", 'Ш'),
    CYRILLIC_SHCHA("cyrillic_shcha", 'Щ'),
    CYRILLIC_HARD_SIGN("cyrillic_hard_sign", 'Ъ'),
    CYRILLIC_YERU("cyrillic_yeru", 'Ы'),
    CYRILLIC_SOFT_SIGN("cyrillic_soft_sign", 'Ь'),
    CYRILLIC_E("cyrillic_e", 'Э'),
    CYRILLIC_YU("cyrillic_yu", 'Ю'),
    CYRILLIC_YA("cyrillic_ya", 'Я'),
    STAR("star", '★'),
    DIAMOND("diamond", '♦'),
    HEART("heart", '♥'),
    SPADE("spade", '♠'),
    CLUB("club", '♣'),
    EXCLAMATION("exclamation", '!'),
    QUESTION("question", '?'),
    AMPERSAND("ampersand", '&');

    private final String id;
    private final char character;

    NeonGlyph(String id, char character) {
        this.id = id;
        this.character = character;
    }

    /** Texture and model name, {@code textures/block/neon/<id>.png}. */
    public String id() {
        return id;
    }

    public char character() {
        return character;
    }
}
